package vn.smartfarm.iot.irrigation;

import com.fasterxml.jackson.databind.*;
import java.sql.Timestamp;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.annotation.*;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.control.*;

/** Explicit operator steps only: reserve a durable identity, commit, then invoke existing guarded dispatch. */
@Service
public class IrrigationSession {
 public record Start(UUID sessionId,int circuitRevision,int zoneRevision,UUID pumpBootId,UUID valveBootId,int durationSeconds,Instant reviewedAt) {}
 public record Action(UUID requestId,String action,long expectedRevision,Instant reviewedAt) {}
 public record Run(UUID sessionId,IrrigationCircuits.Config config,UUID pumpBootId,UUID valveBootId,int durationSeconds,Instant requestedAt,Instant createdAt,long revision,String phase,boolean stopRequested,String reason,UUID openId,UUID onId,UUID offId,UUID closeId,Instant finishedAt) {}
 public record Operation(UUID requestId,UUID sessionId,String action,JsonNode definition,JsonNode payload,String state,JsonNode result) {}
 public record View(String mode,String circuitId,Instant asOf,boolean enabled,String startReason,boolean canStart,boolean canOpen,boolean canOn,boolean canOff,boolean canClose,boolean canFinish,PumpService.Status pump,CircuitValveControl.Snapshot valve,Run active,List<Run> recent,List<Operation> operations) {}
 public record Receipt(Operation operation,Run session) {}
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IrrigationCircuits circuits;private final CircuitValveControl valves;private final PumpService pump;private final PumpCommandFencing fencing;private final PumpCircuitProof proof;private final TransactionTemplate tx;private final boolean enabled,legacy;
 private volatile boolean ready;
 public IrrigationSession(JdbcTemplate jdbc,ObjectMapper mapper,IrrigationCircuits circuits,CircuitValveControl valves,PumpService pump,PumpCommandFencing fencing,PumpCircuitProof proof,PlatformTransactionManager manager,@Value("${smartfarm.irrigation.session-enabled:false}")boolean enabled,@Value("${smartfarm.irrigation.demo-enabled:false}")boolean legacy){this.jdbc=jdbc;this.mapper=mapper;this.circuits=circuits;this.valves=valves;this.pump=pump;this.fencing=fencing;this.proof=proof;this.enabled=enabled;this.legacy=legacy;tx=new TransactionTemplate(manager);}
 @org.springframework.context.event.EventListener(org.springframework.boot.context.event.ApplicationReadyEvent.class)
 public void interruptOnStartup(){tx.executeWithoutResult(t->{gates();jdbc.update("UPDATE irrigation_session SET phase='RECOVERY_REQUIRED',stop_requested=true,reason='BACKEND_RESTARTED',revision=revision+1 WHERE phase<>'CLOSED_CONFIRMED'");jdbc.update("UPDATE irrigation_session_action SET state='UNRESOLVED' WHERE state='RESERVED'");});ready=true;}
 private void gates(){jdbc.queryForObject("SELECT singleton FROM pump_dispatch_gate WHERE singleton=1 FOR UPDATE",Integer.class);jdbc.queryForObject("SELECT revision FROM irrigation_circuit_state WHERE singleton=1 FOR UPDATE",Long.class);}
 private Run map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Run(r.getObject("session_id",UUID.class),read(r.getString("config_snapshot"),IrrigationCircuits.Config.class),r.getObject("pump_boot",UUID.class),r.getObject("valve_boot",UUID.class),r.getInt("duration_seconds"),r.getTimestamp("requested_at").toInstant(),r.getTimestamp("created_at").toInstant(),r.getLong("revision"),r.getString("phase"),r.getBoolean("stop_requested"),r.getString("reason"),r.getObject("open_id",UUID.class),r.getObject("on_id",UUID.class),r.getObject("off_id",UUID.class),r.getObject("close_id",UUID.class),r.getTimestamp("finished_at")==null?null:r.getTimestamp("finished_at").toInstant());}
 private <T>T read(String value,Class<T> type){if(value==null)return null;try{return mapper.readValue(value,type);}catch(Exception e){throw new IllegalStateException(e);}}
 private JsonNode json(String value){return read(value,JsonNode.class);}
 private String encode(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 public Run find(String circuit,UUID id){var r=jdbc.query("SELECT * FROM irrigation_session WHERE session_id=? AND circuit_id=?",this::map,id,circuit);if(r.isEmpty())throw bad(HttpStatus.NOT_FOUND,"Session not found");return r.getFirst();}
 private Run active(){return jdbc.query("SELECT * FROM irrigation_session WHERE phase<>'CLOSED_CONFIRMED'",this::map).stream().findFirst().orElse(null);}
 public Operation operation(String circuit,UUID id){var rows=jdbc.query("SELECT a.* FROM irrigation_session_action a JOIN irrigation_session s USING(session_id) WHERE a.request_id=? AND s.circuit_id=?",(r,n)->new Operation(id,r.getObject("session_id",UUID.class),r.getString("action"),json(r.getString("definition")),json(r.getString("payload")),r.getString("state"),json(r.getString("result"))),id,circuit);if(rows.isEmpty())throw bad(HttpStatus.NOT_FOUND,"Operation not found");return rows.getFirst();}
 private boolean idle(){try{PumpCircuitRoute.requireIdle(jdbc);var s=pump.status();return s.fresh()&&s.reportedState().equals("OFF")&&s.commandFence().deviceEnabled()&&!s.commandFence().restartRequired()&&jdbc.queryForObject("SELECT count(*) FROM pump_command WHERE state IN ('PENDING','SENT','PUBLISH_UNCERTAIN') OR (target_boot_id=? AND fence_ordinal>?)",Long.class,s.commandFence().intent()==null?null:s.commandFence().intent().bootId(),s.commandFence().lastOrdinal())==0;}catch(ResponseStatusException e){return false;}}
 private boolean allClosed(){for(var c:jdbc.query("SELECT * FROM irrigation_circuit ORDER BY circuit_id",IrrigationCircuits::map)){var s=valves.snapshot(c.circuitId());if(!s.config().expectedSource().equals("SIMULATOR")||!s.config().controllerId().matches("IRRIGATION(0[2-9]|[1-9][0-9])")||s.latest()==null||!CircuitValveControl.fresh(s.latest(),Instant.now())||!s.config().equals(s.latest().config())||!s.latest().demoEnabled()||!s.latest().gpioState().equals("CLOSED")||!s.latest().positionFeedback().closed()||!s.configurationState().equals("CURRENT")||jdbc.queryForObject("SELECT count(*) FROM circuit_demo_command WHERE valve_id=? AND boot_id=? AND ordinal>?",Long.class,c.valveId(),s.latest().bootId(),s.latest().lastOrdinal())>0)return false;}return true;}
 private boolean stoppedAfter(Run r){if(!idle())return false;Instant dispatch=jdbc.query("SELECT issued_at FROM pump_command WHERE command_id=?",(s,n)->s.getTimestamp(1).toInstant(),r.offId()==null?r.sessionId():r.offId()).stream().findFirst().orElse(null);return dispatch!=null&&pump.status().observedAt().isAfter(dispatch);}
 private boolean closedAfter(Run r,CircuitValveControl.Snapshot v){if(!stoppedAfter(r)||r.closeId()==null||v.latest()==null||!v.latest().config().equals(r.config())||!v.latest().gpioState().equals("CLOSED")||!v.latest().positionFeedback().closed()||!CircuitValveControl.fresh(v.latest(),Instant.now()))return false;try{var c=valves.lookup(r.config().circuitId(),r.closeId());return c.state().equals("EXECUTED")&&v.latest().bootId().equals(c.bootId())&&v.latest().lastOrdinal()>=c.ordinal()&&!v.latest().observedAt().isBefore(c.issuedAt());}catch(ResponseStatusException e){return false;}}
 private String startReason(IrrigationCircuits.Config c,CircuitValveControl.Snapshot v,PumpService.Status p){if(!enabled||!ready||legacy)return "PROFILE_DISABLED";var water=vn.smartfarm.iot.nodes.CircuitWaterGate.inspect(jdbc,c.circuitId(),Instant.now());if(!water.allowed())return "WATER_"+water.state();var weather=vn.smartfarm.iot.nodes.ZoneRainGate.inspect(jdbc,c.zoneId(),Instant.now());if(!weather.allowed())return "WEATHER_"+weather.state();if(!p.controlEnabled()||!p.commandFence().required()||!p.commandFence().compatible()||p.commandFence().intent()==null||!p.commandFence().intent().ready())return "PUMP_PROFILE_NOT_READY";if(!PumpCircuitRoute.from(c).equals(p.commandFence().circuitRoute()))return "PUMP_ROUTE_MISMATCH";if(!proof.snapshot(c.circuitId()).connected())return "PUMP_OFFLINE";if(!idle()||p.safetyLockout())return "PUMP_NOT_IDLE";if(!v.enabled()||!v.connected()||!v.readyToOpen()||!allClosed())return "VALVES_NOT_READY";return "READY";}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public View snapshot(String id){var c=circuits.find(id);var p=pump.status();var v=valves.snapshot(id);var r=active();String reason=r==null?startReason(c,v,p):"SESSION_ACTIVE";boolean own=r!=null&&r.config().circuitId().equals(id),on=false;
  if(own&&enabled&&!r.stopRequested()&&r.phase().equals("WAIT_OPEN")&&r.onId()==null){try{var b=proof.snapshot(id);on=b.readyToStart()&&b.maximumSeconds()>=r.durationSeconds()&&b.route().equals(PumpCircuitRoute.from(r.config()))&&p.commandFence().intent().bootId().equals(r.pumpBootId())&&v.latest()!=null&&v.latest().bootId().equals(r.valveBootId());}catch(RuntimeException ignored){on=false;}}
  boolean movable=own&&!r.phase().startsWith("DISPATCHING_");var ops=own?jdbc.query("SELECT request_id FROM irrigation_session_action WHERE session_id=? ORDER BY created_at DESC,request_id DESC LIMIT 20",(s,n)->operation(id,s.getObject(1,UUID.class)),r.sessionId()):List.<Operation>of();
  return new View("OPERATOR_STEPS",id,Instant.now(),enabled,reason,r==null&&reason.equals("READY"),own&&enabled&&!r.stopRequested()&&r.phase().equals("PREPARED")&&startReason(c,v,p).equals("READY")&&p.commandFence().intent().bootId().equals(r.pumpBootId())&&v.latest().bootId().equals(r.valveBootId()),on,own, movable&&r.stopRequested()&&stoppedAfter(r)&&v.latest()!=null&&v.latest().config().equals(r.config()),own&&r.phase().equals("WAIT_CLOSED")&&closedAfter(r,v),p,v,r,jdbc.query("SELECT * FROM irrigation_session WHERE circuit_id=? ORDER BY created_at DESC LIMIT 10",this::map,id),ops);
 }
 public Run start(String id,Start input){if(input==null||input.sessionId()==null||input.pumpBootId()==null||input.valveBootId()==null||input.reviewedAt()==null||input.durationSeconds()<1||input.durationSeconds()>10||input.circuitRevision()<1||input.zoneRevision()<1)throw bad(HttpStatus.BAD_REQUEST,"Invalid session");var request=new Start(input.sessionId(),input.circuitRevision(),input.zoneRevision(),input.pumpBootId(),input.valveBootId(),input.durationSeconds(),input.reviewedAt().truncatedTo(ChronoUnit.MICROS));return tx.execute(t->{gates();var old=jdbc.query("SELECT * FROM irrigation_session WHERE session_id=?",this::map,request.sessionId());if(!old.isEmpty()){var s=old.getFirst();if(!s.config().circuitId().equals(id)||s.config().revision()!=request.circuitRevision()||s.config().zoneRevision()!=request.zoneRevision()||!s.pumpBootId().equals(request.pumpBootId())||!s.valveBootId().equals(request.valveBootId())||s.durationSeconds()!=request.durationSeconds()||!s.requestedAt().equals(request.reviewedAt()))throw bad(HttpStatus.CONFLICT,"Session ID reused");return s;}
  fresh(request.reviewedAt());vn.smartfarm.iot.nodes.CircuitFlowGuard.requireDuration(jdbc,id,request.durationSeconds());var v=snapshot(id);if(!v.canStart()||v.valve().config().revision()!=request.circuitRevision()||v.valve().config().zoneRevision()!=request.zoneRevision()||!v.pump().commandFence().intent().bootId().equals(request.pumpBootId())||!v.valve().latest().bootId().equals(request.valveBootId()))throw bad(HttpStatus.CONFLICT,"Review current ready circuit/boot");
  jdbc.update("INSERT INTO irrigation_session(session_id,circuit_id,config_snapshot,pump_boot,valve_boot,duration_seconds,requested_at,phase,reason) VALUES(?,?,?::jsonb,?,?,?,?,'PREPARED','OPERATOR_CREATED')",request.sessionId(),id,encode(v.valve().config()),request.pumpBootId(),request.valveBootId(),request.durationSeconds(),Timestamp.from(request.reviewedAt()));jdbc.update("UPDATE watering_rule SET enabled=false,low_count=0,last_result='MANUAL_HOLD',execution_epoch=execution_epoch+1 WHERE singleton=1");return find(id,request.sessionId());});}
 public Receipt act(String circuit,UUID session,Action input){if(input==null||input.requestId()==null||input.action()==null||!Set.of("OPEN","ON","OFF","CLOSE","FINISH").contains(input.action())||input.reviewedAt()==null||input.expectedRevision()<1)throw bad(HttpStatus.BAD_REQUEST,"Invalid step");var a=new Action(input.requestId(),input.action(),input.expectedRevision(),input.reviewedAt().truncatedTo(ChronoUnit.MICROS));boolean[] dispatch={false};Operation op=tx.execute(t->{gates();var exists=jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM irrigation_session_action WHERE request_id=?)",Boolean.class,a.requestId());if(Boolean.TRUE.equals(exists)){var old=operation(circuit,a.requestId());if(!old.sessionId().equals(session)||!read(old.definition().toString(),Action.class).equals(a))throw bad(HttpStatus.CONFLICT,"Step ID reused");return old;}
  var r=find(circuit,session);if(r.phase().equals("CLOSED_CONFIRMED"))throw bad(HttpStatus.CONFLICT,"Session finished");fresh(a.reviewedAt());if(!a.action().equals("OFF")&&a.expectedRevision()!=r.revision())throw bad(HttpStatus.CONFLICT,"Session changed");var v=snapshot(circuit);boolean permitted=switch(a.action()){case "OPEN"->v.canOpen();case "ON"->v.canOn();case "OFF"->v.canOff();case "CLOSE"->v.canClose();default->v.canFinish();};if(!permitted)throw bad(HttpStatus.CONFLICT,"Step not ready; read device evidence");
  String phase=switch(a.action()){case "OPEN"->"DISPATCHING_OPEN";case "ON"->"DISPATCHING_ON";case "OFF"->"DISPATCHING_OFF";case "CLOSE"->"DISPATCHING_CLOSE";default->"CLOSED_CONFIRMED";};Object payload=null;
  if(Set.of("OPEN","CLOSE").contains(a.action()))payload=new CircuitValveControl.Request(a.requestId(),a.action(),a.action().equals("OPEN")?30:null,a.action().equals("CLOSE")?v.valve().latest().bootId():r.valveBootId(),r.config().revision(),r.config().zoneRevision(),a.reviewedAt());
  else if(Set.of("ON","OFF").contains(a.action())){var c=v.pump().commandFence().intent();if(c==null||!c.ready())throw bad(HttpStatus.CONFLICT,"Pump intent unavailable");payload=new PumpCommandFencing.HttpIntent(a.requestId(),a.action(),a.action().equals("ON")?r.durationSeconds():null,a.action().equals("OFF")?null:r.pumpBootId(),c.revision(),a.reviewedAt(),a.action().equals("OFF")?null:PumpCircuitRoute.from(r.config()));}
  jdbc.update("INSERT INTO irrigation_session_action(request_id,session_id,action,definition,payload,state) VALUES(?,?,?,?::jsonb,?::jsonb,?)",a.requestId(),session,a.action(),encode(a),payload==null?null:encode(payload),a.action().equals("FINISH")?"RETURNED":"RESERVED");
  String column=switch(a.action()){case "OPEN"->"open_id";case "ON"->"on_id";case "OFF"->"off_id";case "CLOSE"->"close_id";default->null;};jdbc.update("UPDATE irrigation_session SET phase=?,reason=?,revision=revision+1,stop_requested=stop_requested OR ?,finished_at=CASE WHEN ?='CLOSED_CONFIRMED' THEN CURRENT_TIMESTAMP ELSE finished_at END"+(column==null?"":","+column+"=?")+" WHERE session_id=?",column==null?new Object[]{phase,"OPERATOR_"+a.action(),a.action().equals("OFF"),phase,session}:new Object[]{phase,"OPERATOR_"+a.action(),a.action().equals("OFF"),phase,a.requestId(),session});dispatch[0]=!a.action().equals("FINISH");return operation(circuit,a.requestId());});
  if(dispatch[0])dispatchReserved(circuit,session,a,op,()->{});
  return new Receipt(operation(circuit,a.requestId()),find(circuit,session));
 }
 private void dispatchReserved(String circuit,UUID session,Action a,Operation op,Runnable beforeCommit){JsonNode result=null;boolean returned=false;try{result=Set.of("OPEN","CLOSE").contains(a.action())?mapper.valueToTree(valves.create(circuit,mapper.treeToValue(op.payload(),CircuitValveControl.Request.class))):mapper.valueToTree(fencing.createHttp(mapper.treeToValue(op.payload(),PumpCommandFencing.HttpIntent.class),beforeCommit));returned=true;}catch(Exception ignored){/* Keep identity even if dispatch outcome is unknown; never replay. */}
   final JsonNode output=result;final boolean ok=returned;tx.executeWithoutResult(t->{gates();jdbc.update("UPDATE irrigation_session_action SET state=?,result=?::jsonb WHERE request_id=?",ok?"RETURNED":"UNRESOLVED",output==null?null:encode(output),a.requestId());String waiting=ok?(a.action().equals("CLOSE")?"WAIT_CLOSED":"WAIT_"+a.action()):"RECOVERY_REQUIRED";jdbc.update("UPDATE irrigation_session SET phase=?,reason=?,revision=revision+1,stop_requested=stop_requested OR ? WHERE session_id=? AND phase=? AND "+switch(a.action()){case "OPEN"->"open_id";case "ON"->"on_id";case "OFF"->"off_id";default->"close_id";}+"=?",waiting,ok?"CHECK_DEVICE_EVIDENCE":"STEP_UNRESOLVED",!ok,session,"DISPATCHING_"+a.action(),a.requestId());});
 }
 /** One durable OFF attempt per active operator session. No replay after a crash or uncertain publish. */
 private enum StopCause { WEATHER, WATER, FLOW }
 public void stopForWeather(){stopForCondition(StopCause.WEATHER);}
 public void stopForWater(){stopForCondition(StopCause.WATER);}
 public void stopForFlow(){stopForCondition(StopCause.FLOW);}
 private void stopForCondition(StopCause cause){
  boolean weatherCause=cause==StopCause.WEATHER;
  if(!enabled||!ready||legacy)return;
  Operation op=tx.execute(t->{gates();var r=active();if(r==null||r.stopRequested()||r.onId()==null||!Set.of("DISPATCHING_ON","WAIT_ON").contains(r.phase()))return null;
   JsonNode evidence;String reason;String eventTable=switch(cause){case WEATHER->"irrigation_weather_stop";case WATER->"irrigation_water_stop";case FLOW->"irrigation_flow_stop";};
   if(weatherCause){var weather=vn.smartfarm.iot.nodes.ZoneRainGate.inspect(jdbc,r.config().zoneId(),Instant.now());if(weather.policy()==null||!weather.policy().enabled()||!weather.policy().stopOnRain()||weather.allowed())return null;evidence=mapper.valueToTree(weather);reason="WEATHER_"+weather.state();}
   else if(cause==StopCause.WATER){var water=vn.smartfarm.iot.nodes.CircuitWaterGate.inspect(jdbc,r.config().circuitId(),Instant.now());if(water.policy()==null||!water.policy().enabled()||!water.policy().stopOnUnavailable()||water.allowed())return null;evidence=mapper.valueToTree(water);reason="WATER_"+water.state();}
   else{var flow=vn.smartfarm.iot.nodes.CircuitFlowGuard.inspect(jdbc,r.config().circuitId(),Instant.now(),true);if(!flow.stopRequired())return null;evidence=mapper.valueToTree(flow);reason="FLOW_"+flow.state();}
   // All evaluators hold the same gates and respect the same session stop latch.
   if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM "+eventTable+" WHERE session_id=?)",Boolean.class,r.sessionId())))return null;
   UUID id=UUID.randomUUID();var at=Instant.now().truncatedTo(ChronoUnit.MICROS);var a=new Action(id,"OFF",r.revision(),at);var c=fencing.view().intent();boolean canDispatch=c!=null&&c.ready();
   var payload=canDispatch?new PumpCommandFencing.HttpIntent(id,"OFF",null,null,c.revision(),at,null):null;
   jdbc.update("INSERT INTO irrigation_session_action(request_id,session_id,action,definition,payload,state) VALUES(?,?,'OFF',?::jsonb,?::jsonb,?)",id,r.sessionId(),encode(a),encode(payload),canDispatch?"RESERVED":"UNRESOLVED");
   jdbc.update("INSERT INTO "+eventTable+"(session_id,request_id,"+(weatherCause?"zone_id":"circuit_id")+",evidence) VALUES(?,?,?,?::jsonb)",r.sessionId(),id,weatherCause?r.config().zoneId():r.config().circuitId(),encode(evidence));
   jdbc.update("UPDATE irrigation_session SET stop_requested=true,phase=?,reason=?,off_id=?,revision=revision+1 WHERE session_id=?",canDispatch?"DISPATCHING_OFF":"RECOVERY_REQUIRED",reason,id,r.sessionId());
   return operation(r.config().circuitId(),id);
  });
  if(op==null||!op.state().equals("RESERVED"))return;
  String circuit=jdbc.queryForObject("SELECT circuit_id FROM irrigation_session WHERE session_id=?",String.class,op.sessionId());var a=read(op.definition().toString(),Action.class);
  dispatchReserved(circuit,op.sessionId(),a,op,()->{
   // Executed inside pump_dispatch_gate before command reservation commits. A late automatic OFF
   // must not affect a newer manual stop or a later session that now owns the pump.
   if(jdbc.queryForObject("SELECT count(*) FROM irrigation_session WHERE session_id=? AND off_id=? AND phase='DISPATCHING_OFF' AND stop_requested",Integer.class,op.sessionId(),op.requestId())!=1)throw bad(HttpStatus.CONFLICT,"Automatic stop superseded; never replay");
  });
 }
 private static void fresh(Instant at){if(at.isBefore(Instant.now().minusSeconds(10))||at.isAfter(Instant.now().plusSeconds(2)))throw bad(HttpStatus.CONFLICT,"Review expired");}
 private static ResponseStatusException bad(HttpStatus code,String text){return new ResponseStatusException(code,text);}
}
